package com.paytrace.simulator;
import com.paytrace.investigation.*; import com.paytrace.payment.*; import com.paytrace.webhook.*; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.concurrent.*;
@Service public class ScenarioLab { private final PaymentService payments;private final InvestigationService investigations;private final WebhookInboxService webhooks;private final Map<UUID,ScenarioRun> runs=new ConcurrentHashMap<>();public ScenarioLab(PaymentService p,InvestigationService i,WebhookInboxService w){payments=p;investigations=i;webhooks=w;}
 public ScenarioRun run(Scenario scenario){String key="scenario-"+scenario+"-"+UUID.randomUUID();CreatePaymentRequest request=new CreatePaymentRequest("order-"+UUID.randomUUID().toString().substring(0,8),new BigDecimal("8000.00"),"INR");PaymentView payment;var observations=new ArrayList<String>();try{payment=payments.create(request,key,scenario.fault());}catch(Exception e){observations.add(e.getMessage());payment=payments.create(request,key,com.paytrace.provider.ProviderFaultMode.NORMAL);}if(scenario==Scenario.DUPLICATE_CLIENT_RETRY||scenario==Scenario.TIMEOUT_AFTER_PROVIDER_CAPTURE){payments.create(request,key,com.paytrace.provider.ProviderFaultMode.NORMAL);observations.add("Client retry produced an idempotency replay.");}if(scenario==Scenario.DUPLICATE_WEBHOOK){var hook=new ProviderWebhook("evt_"+UUID.randomUUID(),payment.paymentId(),PaymentEventType.PROVIDER_CAPTURED,Instant.now(),"capture");webhooks.receive(hook);webhooks.receive(hook);observations.add("Second webhook was persisted as duplicate evidence.");}if(scenario==Scenario.OUT_OF_ORDER_WEBHOOK){var at=Instant.now();webhooks.receive(new ProviderWebhook("evt_settled_"+UUID.randomUUID(),payment.paymentId(),PaymentEventType.PAYMENT_SETTLED,at.plusSeconds(20),"settled"));webhooks.receive(new ProviderWebhook("evt_auth_"+UUID.randomUUID(),payment.paymentId(),PaymentEventType.PAYMENT_AUTHORIZED,at,"authorized"));observations.add("Timeline is reconstructed from occurredAt rather than arrival order.");}var result=new ScenarioRun(UUID.randomUUID(),scenario,payment.paymentId(),investigations.investigate(payment.paymentId()),List.copyOf(observations));runs.put(result.runId(),result);return result;} public Optional<ScenarioRun> get(UUID id){return Optional.ofNullable(runs.get(id));} public List<Scenario> scenarios(){return List.of(Scenario.values());}}
